# === Fragment: 02_info_mark.py ===
"""Kernel fragment: 02_info_mark — Epistemic DAG model.

Core rules:
  State before reasoning. Decompose before expansion.
  Reference outranks inference. Preserve provenance.
  Do not promote claims without verification.
  Use the weakest dependency as the conclusion ceiling.
  Separate incompatible standards.
  Emit the cleanest verified next state.

Node types:
  Unknown      = empty node
  Guess        = candidate node
  Hypothetical = externally supported phantom node
  Inferred     = dependency-linked derived node
  Exact        = scope-bounded verified node
"""


import uuid
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any, Optional

# ---------------------------------------------------------------------------
# EpistemicStatus — single enum for epistemic level
# ---------------------------------------------------------------------------

class EpistemicStatus(str):
    """Epistemic level of a piece of information.

    Order: Unknown < Guess < Hypothetical < Inferred < Exact
    """

    UNKNOWN = "Unknown"
    GUESS = "Guess"
    HYPOTHETICAL = "Hypothetical"
    INFERRED = "Inferred"
    EXACT = "Exact"

    _values = frozenset({UNKNOWN, GUESS, HYPOTHETICAL, INFERRED, EXACT})

    def __new__(cls, value: str) -> "EpistemicStatus":
        if value not in cls._values:
            raise ValueError(f"Invalid EpistemicStatus: {value!r}. Must be one of {sorted(cls._values)}")
        return str.__new__(cls, value)  # type: ignore[call-overload]

    def __eq__(self, other: object) -> bool:
        if isinstance(other, EpistemicStatus):
            return str(self) == str(other)
        if isinstance(other, str):
            return str(self) == other
        return NotImplemented

    def __hash__(self) -> int:
        return hash(str(self))

    def __lt__(self, other: "EpistemicStatus") -> bool:
        return _STATUS_ORDER[str(self)] < _STATUS_ORDER[str(other)]

    def __le__(self, other: "EpistemicStatus") -> bool:
        return _STATUS_ORDER[str(self)] <= _STATUS_ORDER[str(other)]


_STATUS_ORDER: dict[str, int] = {
    "Unknown": 0,
    "Guess": 1,
    "Hypothetical": 2,
    "Inferred": 3,
    "Exact": 4,
}


# ---------------------------------------------------------------------------
# ClaimNode — a single epistemic node
# ---------------------------------------------------------------------------

@dataclass
class ClaimNode:
    """Epistemic node in a dependency DAG.

    A claim is Exact only within its declared scope and only while its
    verification holds. A failed oracle demotes Exact → Guess.
    """

    id: str = ""
    text: str = ""
    status: EpistemicStatus = field(default_factory=lambda: EpistemicStatus("Unknown"))
    scope: str = ""                      # what this claim is bounded to
    dependencies: list[str] = field(default_factory=list)  # IDs this depends on
    evidence: str = ""                   # what supports this claim
    falsifier: str = ""                  # what would disprove it
    source: str = ""                     # "oracle" | "code_search" | "web_search" | "inference"
    verified_at: str = ""                # ISO timestamp
    label: str = ""

    def __post_init__(self):
        if not self.id:
            self.id = uuid.uuid4().hex[:12]
        if isinstance(self.status, str) and not isinstance(self.status, EpistemicStatus):
            self.status = EpistemicStatus(self.status)


# ---------------------------------------------------------------------------
# EpistemicDAG — the graph
# ---------------------------------------------------------------------------

@dataclass
class EpistemicDAG:
    """Collection of ClaimNodes with dependency edges."""

    nodes: dict[str, ClaimNode] = field(default_factory=dict)

    def add(self, node: ClaimNode) -> None:
        self.nodes[node.id] = node

    def remove(self, node_id: str) -> None:
        self.nodes.pop(node_id, None)

    def dependencies_of(self, node_id: str) -> list[ClaimNode]:
        """Direct dependencies of a node."""
        node = self.nodes.get(node_id)
        if node is None:
            return []
        return [self.nodes[dep] for dep in node.dependencies if dep in self.nodes]

    def dependents_of(self, node_id: str) -> list[ClaimNode]:
        """All nodes that depend on node_id."""
        return [n for n in self.nodes.values() if node_id in n.dependencies]

    def roots(self) -> list[ClaimNode]:
        """Nodes with no dependencies (externally sourced)."""
        return [n for n in self.nodes.values() if not n.dependencies]

    def derived(self) -> list[ClaimNode]:
        """Nodes with at least one dependency."""
        return [n for n in self.nodes.values() if n.dependencies]


# ---------------------------------------------------------------------------
# CORE RULE: weakest-link ceiling
# ---------------------------------------------------------------------------

def effective_status(node: ClaimNode, dag: EpistemicDAG,
                     _visited: Optional[set[str]] = None) -> EpistemicStatus:
    """A claim is at most as strong as its weakest dependency.

    Exact derived from Guess → at most Guess.
    Cycles are detected and treated as Unknown (circular dependency = broken).
    """
    if _visited is None:
        _visited = set()
    if node.id in _visited:
        return EpistemicStatus("Unknown")
    _visited.add(node.id)

    if not node.dependencies:
        return node.status

    dep_statuses: list[EpistemicStatus] = []
    for dep_id in node.dependencies:
        dep = dag.nodes.get(dep_id)
        if dep is None:
            dep_statuses.append(EpistemicStatus("Unknown"))
        else:
            dep_statuses.append(effective_status(dep, dag, _visited.copy()))

    weakest_dep = min(dep_statuses)
    return min(node.status, weakest_dep)


# ---------------------------------------------------------------------------
# Promotion / demotion gates
# ---------------------------------------------------------------------------

PROMOTION_GATES: dict[tuple[str, str], str] = {
    ("Unknown", "web_search_found"): "Guess",
    ("Guess", "code_search_verified"): "Hypothetical",
    ("Hypothetical", "dependencies_inferred"): "Inferred",
    ("Inferred", "oracle_pass"): "Exact",
}


def promote_claim(node: ClaimNode, dag: EpistemicDAG, new_status: EpistemicStatus,
                  evidence: str = "") -> ClaimNode:
    """Gated promotion. Returns the (possibly promoted) node.

    Promotion only allowed through defined gates. Direct Unknown→Exact
    without verification is forbidden.
    """
    from_s = str(node.status)
    to_s = str(new_status)

    valid = False
    for (f, gate), t in PROMOTION_GATES.items():
        if f == from_s and t == to_s:
            valid = True
            break

    if not valid and _STATUS_ORDER[to_s] > _STATUS_ORDER[from_s]:
        return node

    node.status = new_status
    if evidence:
        node.evidence = evidence
    node.verified_at = datetime.now(timezone.utc).isoformat()
    return node


def demote_claim(node: ClaimNode, dag: EpistemicDAG, reason: str = "",
                 new_status: Optional[EpistemicStatus] = None) -> ClaimNode:
    """Demote a claim and cascade to dependents via weakest-link."""
    if new_status is None:
        if str(node.status) == "Exact":
            new_status = EpistemicStatus("Guess")
        else:
            new_status = EpistemicStatus("Unknown")

    node.status = new_status
    if reason:
        node.evidence = f"DEMOTED: {reason}"

    for dependent in dag.dependents_of(node.id):
        new_effective = effective_status(dependent, dag)
        if str(new_effective) != str(dependent.status):
            dependent.status = new_effective

    return node


def verify_claim(node: ClaimNode, dag: EpistemicDAG,
                 oracle_pass: bool, scope: str = "") -> ClaimNode:
    """Oracle gate: PASS → promote to Exact (scoped). FAIL → demote to Guess."""
    if oracle_pass:
        node.status = EpistemicStatus("Exact")
        node.scope = scope or node.scope
        node.source = "oracle"
        node.verified_at = datetime.now(timezone.utc).isoformat()
    else:
        node = demote_claim(node, dag, reason="oracle FAIL", new_status=EpistemicStatus("Guess"))
    return node


# ---------------------------------------------------------------------------
# classify_claim_status — standalone claim classifier (no DAG)
# ---------------------------------------------------------------------------

def classify_claim_status(
    *,
    has_unresolved_contradiction: bool = False,
    freshness: float = 1.0,
    has_direct_evidence: bool = False,
    all_premises_exact: bool = False,
    derivation_nonempty: bool = False,
    falsifier_specified: bool = False,
    has_any_evidence: bool = False,
    parametric_confidence: float = 0.0,
) -> EpistemicStatus:
    """Classify a standalone claim without dependency context.

    Direct evidence → Exact.
    All premises Exact + derivation → Inferred.
    Falsifier specified → Hypothetical.
    Any evidence → Guess.
    Otherwise → Unknown.

    For dependency-aware classification, use effective_status() with a DAG.
    """
    try:
        fresh = float(freshness)
    except (TypeError, ValueError):
        fresh = 0.0

    if has_unresolved_contradiction or fresh <= 0.0:
        return EpistemicStatus("Unknown")
    if has_direct_evidence and fresh > 0.0:
        return EpistemicStatus("Exact")
    if all_premises_exact and derivation_nonempty:
        return EpistemicStatus("Inferred")
    if falsifier_specified:
        return EpistemicStatus("Hypothetical")
    if has_any_evidence or parametric_confidence > 0.0:
        return EpistemicStatus("Guess")
    return EpistemicStatus("Unknown")


def status_after_oracle_pass(*, claim_scope_ok: bool = True, freshness: float = 1.0) -> EpistemicStatus:
    """Oracle PASS promotes the verified claim to Exact (scoped)."""
    try:
        fresh = float(freshness)
    except (TypeError, ValueError):
        fresh = 0.0
    if not claim_scope_ok or fresh <= 0.0:
        return EpistemicStatus("Unknown")
    return EpistemicStatus("Exact")


# ---------------------------------------------------------------------------
# Confusion matrix — statistical evidence gate
# ---------------------------------------------------------------------------

def confusion_matrix_validation(tp: int, fp: int, tn: int, fn: int) -> dict[str, Any]:
    """Statistical evidence: Hypothetical → Inferred when F1 ≥ 0.8, precision ≥ 0.85."""
    precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    f1 = (2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0)
    promoted = (f1 >= 0.8 and precision >= 0.85)
    return {
        "tp": tp, "fp": fp, "tn": tn, "fn": fn,
        "precision": round(precision, 4), "recall": round(recall, 4), "f1": round(f1, 4),
        "promoted": promoted,
        "new_level": "Inferred" if promoted else "Hypothetical",
    }


# ---------------------------------------------------------------------------
# Salience — attention only, never epistemic status
# ---------------------------------------------------------------------------

def salience_from_mention_ratio(mention_ratio: float) -> float:
    """Salience S(c) ∈ [0,1] from recurrence — attention only, never epistemic."""
    try:
        r = float(mention_ratio)
    except (TypeError, ValueError):
        return 0.0
    if r < 0.0:
        return 0.0
    if r > 1.0:
        return 1.0
    return r


# ---------------------------------------------------------------------------
# Reverse search
# ---------------------------------------------------------------------------

def reverse_search(claims: list[dict[str, Any]], query: str,
                   min_level: str = "Inferred") -> list[dict[str, Any]]:
    """Only Exact and Inferred claims participate in grounding set."""
    level_order = {"Exact": 4, "Inferred": 3, "Hypothetical": 2, "Guess": 1, "Unknown": 0}
    min_val = level_order.get(min_level, 3)
    return [c for c in claims
            if level_order.get(c.get("level", "Unknown"), 0) >= min_val
            and query.lower() in c.get("text", "").lower()]


# ---------------------------------------------------------------------------
# inference_stamp — system-stamped Inferred claims (v6)
# ---------------------------------------------------------------------------
# Previously: only oracle_stamp existed (→ Exact). Inferred had no system
# stamp, making it formally unreachable as a Grounding Set member.
# v6 adds inference_stamp: when all dependencies are grounded (Exact|Inferred)
# AND a derivation rule is declared AND the derivation hash matches,
# the claim is system-stamped Inferred — valid for G (grounding set).


@dataclass
class InferenceStamp:
    """System stamp that promotes a claim to Inferred via validated derivation.

    Unlike oracle_stamp (which requires external PASS/FAIL),
    inference_stamp validates that all dependencies are grounded and
    the derivation is reproducible.
    """
    claim_id: str = ""
    derivation_rule: str = ""        # e.g. "R17", "transitive_closure", "type_inference"
    dependencies: list[str] = field(default_factory=list)
    dependency_effective_status: str = ""  # weakest among deps (must be ≥ Inferred)
    derivation_hash: str = ""        # deterministic hash of derivation inputs
    stamped_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    result: str = ""                 # "VALID" | "INVALID"

    def is_valid(self, dag: EpistemicDAG) -> bool:
        """Check that all dependencies are grounded and derivation is sound."""
        if not self.dependencies:
            return False
        if not self.derivation_rule:
            return False
        if self.result != "VALID":
            return False

        # All dependencies must be ≥ Inferred (grounded)
        dep_statuses: list[EpistemicStatus] = []
        for dep_id in self.dependencies:
            dep = dag.nodes.get(dep_id)
            if dep is None:
                return False
            eff = effective_status(dep, dag)
            dep_statuses.append(eff)

        weakest = min(dep_statuses)
        if str(weakest) not in ("Inferred", "Exact"):
            return False

        self.dependency_effective_status = str(weakest)
        return True


def stamp_inferred(
    node: ClaimNode,
    dag: EpistemicDAG,
    stamp: InferenceStamp,
) -> ClaimNode:
    """Apply inference_stamp → promote to Inferred if valid.

    Preconditions (all must hold):
      1. All dependencies are grounded (≥ Inferred effective_status)
      2. A derivation rule is declared
      3. The derivation hash matches
      4. stamp.result == "VALID"

    This is the missing piece: system-stamped Inferred claims can now
    participate in Grounding Set G alongside Exact claims.
    """
    if not stamp.is_valid(dag):
        return node

    stamp.claim_id = node.id
    stamp.stamped_at = datetime.now(timezone.utc).isoformat()

    node.status = EpistemicStatus("Inferred")
    node.source = f"inference::{stamp.derivation_rule}"
    node.evidence = f"stamp:{stamp.derivation_hash[:12]}"
    node.verified_at = stamp.stamped_at

    return node


def compute_inference_hash(
    dependencies: list[str],
    rule: str,
    inputs: dict[str, Any],
) -> str:
    """Deterministic hash of inference inputs for reproducibility."""
    import hashlib
    import json
    canonical = json.dumps({
        "deps": sorted(dependencies),
        "rule": rule,
        "inputs": dict(sorted(inputs.items())),
    }, sort_keys=True, default=str)
    return hashlib.sha256(canonical.encode()).hexdigest()[:16]

# === Fragment: 03_semantic_vector.py ===
"""Kernel fragment: 03_semantic_vector (former monofile L259-297)."""


@dataclass
class SemanticVector:
    """§III Keyword-weight pairs with normalized weights.
    Two hash domains: md5_msg_tag (content provenance), md5_sv_tag (semantic anchor).
    """
    keywords: list[str] = field(default_factory=list)
    weights: list[float] = field(default_factory=list)
    semantic_dominant: str = ""

    def __post_init__(self):
        if self.weights and sum(self.weights) > 0:
            total = sum(self.weights)
            self.weights = [round(w / total, 4) for w in self.weights]

    def canonical_string(self) -> str:
        """Canonical SV: dominant=<d>|k1:w1|k2:w2|... (keys sorted)."""
        pairs = sorted(zip(self.keywords, self.weights), key=lambda x: x[0])
        parts = [f"dominant={self.semantic_dominant}"]
        parts.extend(f"{k}:{w}" for k, w in pairs)
        return "|".join(parts)

    def md5_sv_tag(self) -> str:
        """Semantic anchor checksum from canonical SV string."""
        return hashlib.md5(self.canonical_string().encode("utf-8")).hexdigest()


def build_semantic_vector(keywords: list[str], weights: list[float],
                          dominant: str = "") -> SemanticVector:
    """Build and auto-normalize a SemanticVector."""
    return SemanticVector(keywords=keywords, weights=weights, semantic_dominant=dominant)


def md5_msg_tag(content: str) -> str:
    """Message provenance hash — TAB, LF, CR, SPACE stripped before hash."""
    stripped = "".join(c for c in content if c not in "\t\n\r ")
    return hashlib.md5(stripped.encode("utf-8")).hexdigest()

# === Fragment: 04_delta.py ===
"""Kernel fragment: 04_delta — unified Manhattan (L1) metric throughout the spine.

Single geometry: Manhattan distance on keyword-weight vectors.
d₁(a, b) = Σ|w_a(k) − w_b(k)| over all keys k.

Thresholds:
  DELTA_STABLE = 0.3  — STUCK / CONFIRMATION / stable cluster
  DELTA_SHIFT  = 0.5  — REFINING boundary / candidate filter τ

Cosine and blended metrics removed: L1 is the only geometry for fractal
lattice spaces — it respects topology (holes are real, you cannot walk
through a hole in a Sierpinski gasket).
"""

import math     # noqa: F401 — kept for potential future embedding math


DELTA_STABLE: float = 0.3
DELTA_SHIFT: float = 0.5


def delta_l1(sv_curr: dict[str, float], sv_last: dict[str, float]) -> float:
    """Δ_L1 = sum_{k in K} |w_k_curr - w_k_last| — Manhattan (L1) distance."""
    keys = set(sv_curr.keys()) | set(sv_last.keys())
    return sum(abs(sv_curr.get(k, 0.0) - sv_last.get(k, 0.0)) for k in keys)


def classify_delta(d: float) -> "DeltaClass":
    """< 0.3 Stable, 0.3-0.5 Shift, > 0.5 Divergence."""
    if d < DELTA_STABLE:
        return DeltaClass.STABLE
    elif d < DELTA_SHIFT:
        return DeltaClass.SHIFT
    else:
        return DeltaClass.DIVERGENCE


def adaptive_delta_threshold(
    deltas: list[float],
    margin: float = 0.1,
    fallback: float = 0.3,
    min_n: int = 5,
) -> float:
    """Signal classification threshold from observed noise-signal distribution.

    Fixed δ < 0.3 works for typical sessions, but when signal clusters are
    systematically tighter or looser (different SV granularity, high-noise
    contexts), a fixed threshold can misclassify: CONFIRMATION signals get
    labelled DIVERGENCE and vice versa.

    Strategy: median of observed (non-spike) deltas + `margin`. The median
    captures the "typical" semantic distance in the current context; adding
    a small margin separates CONFIRMATION from DIVERGENCE around that norm.

    Spikes (> 2× median) are excluded before computing — they represent
    true divergences, not normal variation.

    Example:
      deltas = [0.08, 0.10, 0.12, 0.09, 0.85, 0.11]
      median ≈ 0.105 (spike 0.85 excluded)
      → δ_threshold ≈ 0.105 + 0.1 = 0.205
      → 0.08, 0.09, 0.10, 0.11, 0.12 all < 0.205 → CONFIRMATION
      → 0.85 > 0.205 → DIVERGENCE
    """
    if not deltas or len(deltas) < min_n:
        return fallback
    median = sorted(deltas)[len(deltas) // 2]
    if median < 0.001:
        return fallback
    # Exclude spikes > 2× median (true divergences, not normal variation)
    typical = [d for d in deltas if d <= 2.0 * median]
    if len(typical) < min_n:
        return fallback
    median_typical = sorted(typical)[len(typical) // 2]
    return min(0.9, max(0.1, median_typical + margin))

# === Fragment: 05_svm_anchor.py ===
"""Kernel fragment: 05_svm_anchor (former monofile L339-472)."""

import re

_WORD_CHAR = re.compile(r"[\w]", re.UNICODE)


def safe_truncate(text: str, max_len: int) -> str:
    """Truncate to max_len, stepping back to last non-word-char boundary.

    Avoids mid-word splits (e.g. "заверш|ённых") by scanning back up to
    200 chars for a character that is NOT a letter, digit, or underscore.
    Falls back to hard cut at max_len if no boundary found (200+ char word).
    """
    if len(text) <= max_len:
        return text
    cut = max_len
    for i in range(max_len - 1, max(0, max_len - 200), -1):
        if not _WORD_CHAR.match(text[i]):
            cut = i + 1  # include boundary char
            break
    return text[:cut]


@dataclass
class Signal:
    """Incoming information that may confirm or contradict current SV anchor.

    KEY INSIGHT: Cardinality != signal count. 60 identical LSP errors
    from one JSX-resolution bug = 1 effective signal, not 60.

    Disposition semantics (v6 — COLLAPSE, never FILTER OUT):
      - COLLAPSED_DUPLICATES: many identical signals from one root cause.
        Evidential weight is PRESERVED (cardinality recorded, count=1).
        The agent sees "60 errors, 1 root cause" — not "0 errors."
      - CONFIRMATION / DIVERGENCE: actionable signals as before.
    """
    source: str = ""           # "LSP", "typecheck", "test-output", "user-message"
    pattern: str = ""          # clustered key (e.g. "JSX-unresolved-reference")
    cardinality: int = 1       # how many times repeated (preserved for evidence)
    content: str = ""
    information_mark: Optional[EpistemicStatus] = None
    disposition: str = ""      # "" | "COLLAPSED_DUPLICATES" | "CONFIRMATION" | "DIVERGENCE"

    @property
    def effective_weight(self) -> float:
        """Weight = 1.0 regardless of cardinality. One bug × N lines = 1 signal."""
        return 1.0

    @property
    def evidential_weight(self) -> int:
        """Raw cardinality preserved for evidence — never discarded.
        60 collapsed duplicates still show cardinality=60 so the agent
        knows the magnitude, even though effective_weight=1.0."""
        return self.cardinality


@dataclass
class SVMAnchor:
    """Fixed SV at a decision point — the agent's 'I am doing X' state.

    Frozen at phase transitions (plan→design, design→implementation).
    Incoming signals are compared against this anchor, NOT against the
    live conversation state (which may be polluted by noise).
    """
    sv: SemanticVector = field(default_factory=SemanticVector)
    phase: str = ""            # "understanding", "design", "implementation", "verification"
    goal: str = ""
    frozen_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    @property
    def dominant(self) -> str:
        return self.sv.semantic_dominant

    def l1_distance(self, other: "SVMAnchor") -> float:
        """Δ_L1 between this anchor and another SV."""
        return delta_l1(
            dict(zip(self.sv.keywords, self.sv.weights)),
            dict(zip(other.sv.keywords, other.sv.weights)),
        )


def _same_source_repeated(signal: Signal) -> bool:
    """True when many identical signals originate from a single-source bug.

    Detection heuristics (any one suffices):
    1. Cardinality ≥ 5 — pure volume: 5+ identical (source, pattern) signals
       is suspicious regardless of source type.
    2. Content similarity — all signals share a common prefix ≥ 30 chars.
    3. Known cascade sources — compiler/linter cascades with recognizable
       error patterns.
    """
    if signal.cardinality <= 1:
        return False

    # Heuristic 1: pure cardinality (5+ identical signals → suspect cascade)
    if signal.cardinality >= 5:
        return True

    # Heuristic 2: content similarity (common prefix across signals)
    if len(signal.content) >= 30:
        return True

    # Heuristic 3: known cascade sources + patterns
    cascade_sources = {"LSP", "typecheck", "tsgo", "tsc", "eslint", "pylint",
                       "test-output", "runtime-error", "log"}
    if signal.source not in cascade_sources:
        return False
    cascade_patterns = [
        "expected", "unresolved", "does not exist", "cannot find",
        "Declaration or statement expected", "Expression expected",
        "JSX expressions must have one parent element",
        "KeyError", "AttributeError", "TypeError", "NameError",
    ]
    return any(p.lower() in signal.pattern.lower() for p in cascade_patterns)


def classify_signal(anchor: SVMAnchor, signal: Signal) -> str:
    """Compare incoming signal against frozen anchor.

    Returns:
      'COLLAPSED_DUPLICATES' — same-source repeated cascade → 1 effective signal,
                               evidential weight PRESERVED (cardinality recorded).
                               v6: NEVER filter out — COLLAPSE instead.
      'CONFIRMATION'         — signal aligns with anchor (Δ_L1 < DELTA_STABLE)
      'DIVERGENCE'           — high delta, genuinely new information → anchor may need revision

    Example (LSP cascade — v6 behaviour):
      anchor = SVMAnchor(sv=build_semantic_vector(["DirectoryBrowser","add","component"],
                                      [0.5,0.3,0.2], "Adding DirectoryBrowser"),
                         phase="implementation")
      signal = Signal(source="LSP", pattern="JSX-unresolved-reference",
                      cardinality=60, content="';' expected")
      classify_signal(anchor, signal)  # → 'COLLAPSED_DUPLICATES'
      # (was 'NOISE' in v5 — v6 preserves evidential_weight=60)
    """
    # COLLAPSE check FIRST — repeated same-source cascades collapse to 1 signal
    # with preserved cardinality. A storm of 60 identical LSP errors is still
    # EVIDENCE (of one root cause), not nothing.
    if _same_source_repeated(signal):
        return "COLLAPSED_DUPLICATES"

    sv_signal = build_semantic_vector(
        keywords=[signal.pattern, signal.source],
        weights=[0.7, 0.3],
        dominant=safe_truncate(signal.content, 100) if signal.content else signal.pattern,
    )
    d = delta_l1(
        dict(zip(anchor.sv.keywords, anchor.sv.weights)),
        dict(zip(sv_signal.keywords, sv_signal.weights)),
    )

    if d < DELTA_STABLE:
        return "CONFIRMATION"

    return "DIVERGENCE"


def filter_signal_storm(anchor: SVMAnchor, signals: list[Signal]) -> list[Signal]:
    """Cluster signals by (source, pattern). Each cluster = 1 effective signal.

    A storm of 60 identical LSP errors is 1 signal, not 60.
    v6: COLLAPSED_DUPLICATES signals are PRESERVED (not filtered out).
    Their evidential_weight = cardinality is retained so the agent knows
    the magnitude of the root cause. Only the context window is saved.

    Returns ALL signals with disposition set:
      - COLLAPSED_DUPLICATES: collapsed but preserved (was: filtered out)
      - CONFIRMATION + DIVERGENCE: actionable as before

    Example:
      signals = [60 LSP errors with same pattern]
      anchor = SVMAnchor(...)  # "Adding DirectoryBrowser"
      result = filter_signal_storm(anchor, signals)
      # → [Signal(disposition="COLLAPSED_DUPLICATES", cardinality=60)]
      # (was [] in v5 — v6 preserves evidence of the root cause)
    """
    # Cluster by (source, pattern)
    clusters: dict[tuple[str, str], list[Signal]] = {}
    for s in signals:
        key = (s.source or "unknown", s.pattern or "unknown")
        clusters.setdefault(key, []).append(s)

    effective: list[Signal] = []
    for (src, pat), group in clusters.items():
        representative = Signal(
            source=src,
            pattern=pat,
            cardinality=len(group),
            content=group[0].content,
            information_mark=group[0].information_mark,
        )
        # Stamp disposition from classify_signal
        disposition = classify_signal(anchor, representative)
        representative.disposition = disposition
        effective.append(representative)

    # v6: COLLAPSED_DUPLICATES signals are PRESERVED — they carry evidence.
    # Only truly empty/unclassifiable signals are dropped.
    return [s for s in effective if s.disposition != ""]

