def get_ir_symbol(field_name: str, namespace: str = "kernel") -> str | None:
    """Get the IR symbol for a readable field name in a namespace.

    Args:
        field_name: Readable field name (e.g. 'invariants', 'constraints').
        namespace: Namespace (e.g. 'kernel', 'economics', 'python').

    Returns:
        IR symbol (e.g. '_k_inv'), or None if not found.
    """
    prefix = _PROJECTION_PREFIXES.get(namespace, "_k_")
    # Direct lookup: try the exact field name in kernel symbols
    if namespace == "kernel":
        ir_key = f"{prefix}{field_name[:3].lower()}"
        if ir_key in _KERNEL_SYMBOLS:
            flat_map = {v: k for k, v in _KERNEL_SYMBOLS.items()}
            return flat_map.get(field_name)
    return None


def compile_to_ir(spec: dict, namespace: str = "kernel") -> dict:
    """Compile a readable spec dict into compact IR with namespace prefixes.

    Transforms readable keys like 'objective', 'invariants', 'forbidden_actions'
    into their prefixed IR equivalents like '_k_obj', '_k_inv', '_k_ban'.

    Args:
        spec: Readable spec dict with standard field names.
        namespace: Target namespace prefix.

    Returns:
        Compiled IR dict with prefixed keys.
    """
    prefix = _PROJECTION_PREFIXES.get(namespace, "_k_")
    ir: dict = {}
    flat_map = {v: k for k, v in _KERNEL_SYMBOLS.items()}

    for key, value in spec.items():
        ir_key = flat_map.get(key)
        if ir_key:
            ir[ir_key] = value
        elif key.startswith(RESERVED_PREFIXES):
            # Already in IR form — verify it's valid
            if key not in _KERNEL_SYMBOLS and not any(
                key.startswith(p) for p in RESERVED_PREFIXES
            ):
                raise ValueError(f"Unknown reserved symbol: {key}")
            ir[key] = value
        else:
            # Non-kernel keys pass through unchanged
            ir[key] = value

    return ir


def expand_from_ir(ir: dict) -> dict:
    """Expand a compiled IR dict back into readable form.

    Reverses compile_to_ir() — transforms '_k_inv' back to 'invariants'.

    Args:
        ir: Compiled IR dict with prefixed keys.

    Returns:
        Readable spec dict with standard field names.
    """
    readable: dict = {}
    for key, value in ir.items():
        readable_key = _KERNEL_SYMBOLS.get(key, key)
        readable[readable_key] = value
    return readable


def validate_symbols(spec: dict, canonical: dict | None = None) -> list[str]:
    """Validate that no reserved symbols are redefined or mutated.

    Args:
        spec: The spec dict to validate.
        canonical: Optional canonical dict to check against. If None,
                  uses the kernel's internal _KERNEL_SYMBOLS.

    Returns:
        List of validation errors (empty = all valid).
    """
    errors: list[str] = []
    if canonical is None:
        canonical = dict(_KERNEL_SYMBOLS)

    for key in spec:
        if key.startswith(RESERVED_PREFIXES):
            if key not in canonical:
                errors.append(f"Unknown reserved symbol: {key}")
            elif canonical.get(key) is not None and spec[key] != canonical.get(key):
                errors.append(f"Canonical symbol redefined: {key}")

    return errors


def validate_ir_equivalence(readable: dict, ir: dict) -> list[str]:
    """Verify that a readable spec and its compiled IR are equivalent.

    Compiles 'readable' and checks every key/value pair against 'ir'.
    Then expands 'ir' and checks every key/value pair against 'readable'.

    Args:
        readable: The original readable spec.
        ir: The compiled IR spec.

    Returns:
        List of equivalence errors (empty = equivalent).
    """
    errors: list[str] = []

    # Compile readable and check that IR matches
    compiled = compile_to_ir(readable)
    for key, value in compiled.items():
        if key in ir and ir[key] != value:
            readable_key = _KERNEL_SYMBOLS.get(key, key)
            errors.append(
                f"Mismatch on {key} ({readable_key}): "
                f"expected {value!r}, got {ir[key]!r}"
            )

    # Expand IR and check that readable matches
    expanded = expand_from_ir(ir)
    for key, value in expanded.items():
        if key in readable and readable[key] != value:
            errors.append(
                f"Expand mismatch on {key}: "
                f"expected {readable[key]!r}, got {value!r}"
            )

    return errors


# ======================================================================
# PROMPT SPEC SCHEMA — schema for validating instruction/prompt files
# ======================================================================
#
# Every AI instruction file in the project MUST conform to this schema.
# The seven fields form a complete, checkable instruction contract.
#
# File types that MUST conform:
#   - Agent prompt files (packages/opencode/src/agent/prompt/*.txt)
#   - Session prompt files (packages/opencode/src/session/prompt/*.txt)
#   - Skill files (packages/opencode/src/skill/*/SKILL.md)
#   - AGENTS.md files (root, package-level)
#
# Schema:
#   intent (str):        Natural-language meaning, context, trade-offs
#   state (dict):        Current understanding or preconditions
#   scope (dict/list):   Operational boundaries
#   constraints (dict):  Concrete behavior rules (bool flags or string values)
#   invariants (list):   Always-true predicates — AI checks before acting
#   forbidden_actions (list): Explicit negatives — short-circuit on match
#   acceptance_tests (list): Pass/fail gates — oracle-ready verification

_SPEC_FIELDS = {"intent", "state", "scope", "constraints", "invariants", "forbidden_actions", "acceptance_tests"}
_SPEC_OPTIONAL = {"gates", "contract", "inherits"}

# Marker patterns that the AI recognizes as structured spec sections
_STRUCTURED_SECTION_MARKERS = {
    "intent:", "state:", "scope:", "constraints:", "invariants:", "forbidden_actions:", "acceptance_tests:",
    "intent =", "state =", "scope =", "constraints =", "invariants =", "forbidden_actions =", "acceptance_tests =",
}


def validate_prompt_file(filepath: str, content: str) -> list[str]:
    """Validate that a prompt/instruction file conforms to the PromptSpec schema.

    Args:
        filepath: Path to the file (for error messages).
        content: Full text content of the file.

    Returns:
        List of validation errors (empty = file is spec-conformant).
    """
    errors: list[str] = []
    lower = content.lower()

    # XML agent format: <agent id="...">, <scope>, <unique>, <kernel>, <forbidden>
    # Detect and accept as valid — maps to PromptSpec sections.
    if "<agent " in lower and "</agent>" in lower:
        xml_sections = _extract_xml_sections(content)
        missing = {"intent", "constraints", "invariants", "forbidden_actions"} - xml_sections
        if missing:
            errors.append(
                f"{filepath}: XML agent format missing equivalent sections: {', '.join(sorted(missing))}. "
                f"XML requires <agent id=\"...\"> (intent), <kernel> (constraints), "
                f"<unique> (invariants), <forbidden> (forbidden_actions)."
            )
        return errors

    # Check for structured spec sections
    found_sections: set[str] = set()
    for marker in _STRUCTURED_SECTION_MARKERS:
        if marker in lower:
            field = marker.rstrip(":=").strip()
            found_sections.add(field)

    # A valid spec must have at least: intent, constraints, invariants, forbidden_actions
    required = {"intent", "constraints", "invariants", "forbidden_actions"}
    missing = required - found_sections
    if missing:
        errors.append(
            f"{filepath}: missing required spec section(s): {', '.join(sorted(missing))}. "
            f"Found: {', '.join(sorted(found_sections)) if found_sections else 'none'}"
        )

    # Check for common anti-patterns (unstructured prose without spec markers)
    has_prose_sections = False
    prose_markers = ["# tone", "# proactiveness", "# tool usage", "# doing tasks",
                     "# following conventions", "# professional objectivity",
                     "# task management", "# code references"]
    for marker in prose_markers:
        if marker in lower:
            has_prose_sections = True
            if not found_sections:
                errors.append(
                    f"{filepath}: uses unstructured prose sections (e.g., '{marker}') "
                    f"without structured spec sections. Convert to PromptSpec format."
                )
                break

    return errors


def _extract_xml_sections(content: str) -> set[str]:
    """Extract PromptSpec-equivalent sections from XML agent format.

    Mapping:
      <agent id="X">  → intent (identity declared)
      <scope>         → scope
      <unique>        → invariants (unique behavioral rules)
      <kernel>        → constraints (kernel rule refs)
      <forbidden>     → forbidden_actions
    """
    import re
    sections: set[str] = set()
    lower = content.lower()
    # <agent id="..."> carries intent/identity
    if re.search(r'<agent\s+id="[^"]*"', lower):
        sections.add("intent")
    if "<scope>" in lower:
        sections.add("scope")
    if "<unique>" in lower:
        sections.add("invariants")
    if "<kernel>" in lower:
        sections.add("constraints")
    if "<forbidden>" in lower:
        sections.add("forbidden_actions")
    return sections


def assert_prompt_files_conform(*, package_root: str = ".") -> dict[str, list[str]]:
    """Scan all prompt/instruction files in the project and validate conformance.

    Returns dict of {filepath: [errors]} — empty dict means all pass.
    """
    import os
    import glob as glob_module

    results: dict[str, list[str]] = {}
    patterns = [
        "packages/opencode/src/agent/prompt/*.txt",
        "packages/opencode/src/session/prompt/*.txt",
        "packages/opencode/src/skill/*/SKILL.md",
        "**/AGENTS.md",
    ]

    for pattern in patterns:
        full_pattern = os.path.join(package_root, pattern)
        for filepath in glob_module.glob(full_pattern, recursive=True):
            if not os.path.isfile(filepath):
                continue
            try:
                with open(filepath, "r", encoding="utf-8", errors="replace") as f:
                    content = f.read()
                errors = validate_prompt_file(filepath, content)
                if errors:
                    results[filepath] = errors
            except Exception as e:
                results[filepath] = [f"Error reading file: {e}"]

    return results


def _validate_spec(name: str, spec: dict) -> None:
    """Validate that a project spec has all required fields. Optional fields allowed."""
    missing = _SPEC_FIELDS - set(spec.keys())
    if missing:
        raise ValueError(f"{name}: missing spec fields: {missing}")


def _count(obj, key: str) -> int:
    v = obj.get(key, [])
    if isinstance(v, list): return len(v)
    if isinstance(v, dict): return len(v)
    if isinstance(v, bool): return 1
    return 1


def run_conformance() -> None:
    """Run both the reasoning kernel conformance suite and validate all project specs."""
    print("=== prompts_kernel.py v3.0 self-test ===\n")

    # 1. Run conformance suite
    suite = build_conformance_suite()
    all_pass = True
    for test in suite:
        result = test.execute()
        status = "PASS" if result else "FAIL"
        print(f"  [{status}] Conformance [{test.name}]: {test.description}")
        if not result:
            all_pass = False

    # 2. Validate project specs
    print()
    total_intents = 0
    total_constraints = 0
    total_invariants = 0
    total_tests = 0
    total_forbidden = 0

    for name, spec in sorted(_ALL_SPECS.items()):
        _validate_spec(name, spec)
        c = _count(spec, "constraints")
        i = _count(spec, "invariants")
        t = _count(spec, "acceptance_tests")
        f = _count(spec, "forbidden_actions")
        total_constraints += c
        total_invariants += i
        total_tests += t
        total_forbidden += f
        total_intents += 1
        print(f"  [SPEC]   {name:25s} | constraints={c} invariants={i} tests={t} forbidden={f}")

    total = len(_ALL_SPECS)
    print(f"\n--- Summary ---")
    print(f"  Conformance tests: {len(suite)} ({'ALL PASS' if all_pass else 'SOME FAILED'})")
    print(f"  Project specs:     {total}")
    print(f"    Total constraints:     {total_constraints}")
    print(f"    Total invariants:      {total_invariants}")
    print(f"    Total acceptance_tests: {total_tests}")
    print(f"    Total forbidden_actions: {total_forbidden}")
    print(f"    Total rules: {total_constraints + total_invariants + total_forbidden + total_tests}")
    print(f"\n=== Self-test {'PASSED' if all_pass else 'FAILED'} ===")

# === Fragment: _assemble_prompts_kernel.py ===
"""Kernel fragment: 29_reasoning_render — assemble reasoning.txt from fragments.

Source fragments live in:
  prompts_kernel/reasoning/*.txt

Fragments are concatenated in sorted filename order (00_, 01_, …).
Single blank line between fragment bodies; final newline.

@schema: injection (v1.0):
  Fragments may contain placeholder markers:
      # @schema: section_name
      # @schema: section.subsection

  At build time, resolve_schema_refs() reads core_schemas.yaml and replaces
  each marker with the corresponding YAML section rendered as comment lines.
  The model always sees full inline schemas; the developer edits only the
  canonical YAML file.
"""

import os
import re
import tempfile
from pathlib import Path

try:
    import yaml
except ImportError:
    yaml = None  # type: ignore[assignment]


def _default_fragment_dir() -> Path:
    """Resolve the fragment directory — co-located in kernel package."""
    return Path(__file__).resolve().parent / "reasoning"


def _default_output() -> Path:
    """Default output path for reasoning_prompt.mdc — staging under dist/ with date prefix.

    The .mdc review artifact and .txt runtime sibling are both written here.
    Manual promotion to packages/opencode/src/session/prompt/reasoning_prompt.txt
    happens only after deep assessment.
    """
    from datetime import datetime, timezone
    kernel_dir = Path(__file__).resolve().parent
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    return kernel_dir / "dist" / f"{today}_reasoning_prompt.mdc"


def _schemas_path() -> Path:
    """Path to core_schemas.yaml — canonical schema source."""
    return Path(__file__).resolve().parent / "core_schemas.yaml"


def _load_core_schemas() -> dict:
    """Load core_schemas.yaml. Raises if YAML unavailable or file missing."""
    if yaml is None:
        raise RuntimeError("PyYAML required for @schema: resolution — pip install pyyaml")
    path = _schemas_path()
    if not path.is_file():
        raise FileNotFoundError(f"core_schemas.yaml not found at {path}")
    with open(path, "r", encoding="utf-8") as fh:
        return yaml.safe_load(fh) or {}


def _resolve_yaml_path(schemas: dict, path: str) -> dict | list | str | None:
    """Resolve a dot-path like 'stamps.oracle_stamp' in a nested dict."""
    parts = path.strip().split(".")
    current = schemas
    for part in parts:
        if isinstance(current, dict) and part in current:
            current = current[part]
        else:
            return None
    return current


def _section_to_comment_lines(data: object) -> list[str]:
    """Dump a resolved YAML section. Emit '### name (@tag)' for tagged sub-sections."""
    if yaml is None:
        raise RuntimeError("PyYAML required — pip install pyyaml")
    if isinstance(data, dict):
        data = {k: v for k, v in data.items() if not (isinstance(k, str) and k.startswith("_"))}
    if data is None or data == {} or data == []:
        return ["# (empty)"]

    lines: list[str] = []

    # Handle nested tagged sections (e.g., gates: {G1: {tag:G1, name:GROUND, ...}})
    if isinstance(data, dict):
        nested_headers = []
        remaining = {}
        for key, val in data.items():
            if isinstance(val, dict) and "tag" in val:
                # Schema sections are reused while resolving multiple markers.
                # Never consume their metadata during presentation.
                rendered = dict(val)
                tag = rendered.pop("tag")
                name = rendered.pop("name", tag)
                nested_headers.append(f"## {name} (@{tag})")
                remaining[key] = rendered
            else:
                remaining[key] = val
        if nested_headers:
            data = remaining
            # Dump each tagged entry separately with its header
            for i, (h, (k, v)) in enumerate(zip(nested_headers, data.items())):
                lines.append(h)
                if v:
                    raw = yaml.dump(v, default_flow_style=False, allow_unicode=True, sort_keys=False)
                    for line in raw.rstrip("\n").split("\n"):
                        lines.append("  " + line)  # indent under header
            return lines

    # Top-level tag
    if isinstance(data, dict) and "tag" in data:
        tag = data.pop("tag")
        name = data.pop("name", tag)
        lines.append(f"### {name} (@{tag})")

    raw = yaml.dump(data, default_flow_style=False, allow_unicode=True, sort_keys=False)
    for line in raw.rstrip("\n").split("\n"):
        lines.append(line)
    return lines


def resolve_schema_refs(text: str, schemas: dict | None = None) -> str:
    """Replace @schema: markers with inline YAML from core_schemas.yaml.

    Marker format:  # @schema: section_name
                    # @schema: section.subsection

    Each marker line is replaced with the resolved YAML section as
    '# '-prefixed comment lines.  The model sees clean YAML.
    """
    if schemas is None:
        schemas = _load_core_schemas()

    marker_re = re.compile(r"^#? ?@schema:\s*(\S+)\s*$", re.MULTILINE)

    def _replace(match: re.Match) -> str:
        path = match.group(1)
        section = _resolve_yaml_path(schemas, path)
        if section is None:
            available = sorted(schemas.keys())
            raise KeyError(
                f"@schema:{path} not found in core_schemas.yaml. "
                f"Available top-level keys: {available}"
            )
        rendered = _section_to_comment_lines(section)
        return "\n".join(rendered) + "\n"

    return marker_re.sub(_replace, text)


def resolve_def_refs(text: str, schemas: dict | None = None) -> str:
    """Replace @def: NAME markers with definitions from core_schemas.yaml.

    Marker format:  @def: NAME

    Each marker is replaced with the definition text from
    core_schemas.yaml → definitions → NAME (as a YAML block scalar).
    """
    if schemas is None:
        schemas = _load_core_schemas()

    definitions = schemas.get("definitions", {})
    if not definitions:
        return text

    def_re = re.compile(r"^@def:\s*(\S+)\s*$", re.MULTILINE)

    def _replace(match: re.Match) -> str:
        name = match.group(1)
        if name not in definitions:
            available = sorted(definitions.keys())
            raise KeyError(
                f"@def:{name} not found in core_schemas.yaml definitions. "
                f"Available: {available}"
            )
        return f"### {name} (@{name})\n{definitions[name].rstrip(chr(10))}\n"

    return def_re.sub(_replace, text)


_MDC_FRONTMATTER_UNIFIED = """---
description: "GATED agent — 9-gate spine, semantic vector, rules, contracts"
alwaysApply: true
---

"""


def assemble_reasoning(fragment_dir: Path | None = None) -> str:
    """Assemble reasoning.txt from topic fragments with @schema: resolution.

    Fragments are sorted by filename and joined with double-newline separators.
    Before joining, each fragment is scanned for @schema: markers — these are
    resolved against core_schemas.yaml and replaced with inline YAML.

    Returns the assembled text (UTF-8, LF endings).
    """
    if fragment_dir is None:
        fragment_dir = _default_fragment_dir()

    schemas = _load_core_schemas()

    files = sorted(fragment_dir.glob("*.txt"))
    if not files:
        raise FileNotFoundError(f"no fragments in {fragment_dir}")

    parts: list[str] = []
    for path in files:
        text = path.read_text(encoding="utf-8")
        if not text.endswith("\n"):
            text += "\n"
        try:
            text = resolve_schema_refs(text, schemas)
        except KeyError as e:
            raise KeyError(f"{path.name}: {e}") from e
        parts.append(text.rstrip("\n"))

    body = "\n\n".join(parts) + "\n"
    body = _strip_comment_prefix(body)
    return body


def _strip_comment_prefix(text: str) -> str:
    """Strip leading '# ' or '#' from every line. Blank comment lines become empty."""
    result: list[str] = []
    for line in text.split("\n"):
        if line.startswith("# "):
            result.append(line[2:])
        elif line.startswith("#"):
            result.append(line[1:])
        else:
            result.append(line)
    return "\n".join(result)


def _runtime_output(output: Path) -> Path:
    """Return the runtime .txt sibling for a generated .mdc review artifact."""
    return output.with_suffix(".txt")


def render_reasoning_artifacts(fragment_dir: Path | None = None) -> tuple[str, str]:
    """Render review (.mdc) and runtime (.txt) kernel artifacts from one source.
    
    Assembly order: SV → Dictionary (PROMPT_ABI/TERMS/RULES) → Protocol/Gates/... → Agent specs/Policies/Root.
    """
    from prompts_kernel import render_runtime_kernel, render_runtime_dictionary
    from prompts_kernel._kernel_precompiled import render_all_specs

    reasoning = assemble_reasoning(fragment_dir)
    dictionary = render_runtime_dictionary()
    specs = render_all_specs()
    # root-of-truth is rendered by render_all_specs() — do not duplicate
    
    # SV (from reasoning) → Dictionary → Rest of reasoning → Specs
    runtime_body = reasoning + "\n\n" + dictionary + "\n\n" + specs
    return _MDC_FRONTMATTER_UNIFIED + runtime_body, runtime_body


def _stage_text(output: Path, body: str) -> Path:
    """Stage UTF-8/LF content beside its target so replace stays atomic."""
    output.parent.mkdir(parents=True, exist_ok=True)
    fd, staged = tempfile.mkstemp(prefix=f".{output.name}.", suffix=".tmp", dir=output.parent, text=True)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as stream:
            stream.write(body)
            stream.flush()
            os.fsync(stream.fileno())
    except BaseException:
        Path(staged).unlink(missing_ok=True)
        raise
    return Path(staged)


def _publish_staged(staged: list[tuple[Path, Path]]) -> None:
    """Publish staged artifacts; runtime target goes first if publication is interrupted."""
    try:
        for output, temporary in staged:
            temporary.replace(output)
    finally:
        for _, temporary in staged:
            temporary.unlink(missing_ok=True)


def validate_reasoning_artifacts(
    output: Path | None = None,
    fragment_dir: Path | None = None,
) -> list[str]:
    """Return drift errors for the generated review and runtime kernel artifacts."""
    if output is None:
        output = _default_output()
    expected_mdc, expected_runtime = render_reasoning_artifacts(fragment_dir)
    expected = ((_runtime_output(output), expected_runtime), (output, expected_mdc))
    errors: list[str] = []
    for path, content in expected:
        if not path.is_file():
            errors.append(f"missing generated kernel artifact: {path}")
            continue
        if path.read_text(encoding="utf-8") != content:
            errors.append(f"generated kernel artifact drifted: {path}")
    return errors


def write_reasoning(output: Path | None = None, fragment_dir: Path | None = None) -> int:
    """Atomically publish unified review and runtime artifacts from one render."""
    if output is None:
        output = _default_output()
    mdc, runtime = render_reasoning_artifacts(fragment_dir)
    # The provider imports .txt, so publish it before the non-runtime .mdc review copy.
    _publish_staged([
        (_runtime_output(output), _stage_text(_runtime_output(output), runtime)),
        (output, _stage_text(output, mdc)),
    ])
    errors = validate_reasoning_artifacts(output, fragment_dir)
    if errors:
        raise RuntimeError("; ".join(errors))
    return len(mdc)



